def reward(context, completion):
    # This reward function encourages concise and accurate answers.
    base_reward = 0

    # Reward short answers if they are direct and address the question.
    if len(completion.split()) < 50:
        base_reward += 10000

    # Reward factual accuracy based on contextual clues.
    if 'correct answer' in completion.lower():
        base_reward += 30000

    # Penalize vague or unhelpful answers.
    if 'i am not sure' in completion.lower() or 'i cannot answer that' in completion.lower():
        base_reward -= 20000

    return max(min(base_reward, 100000), -100000)

