def reward(context, completion):
    # Encourage responses that are both informative and concise
    informative_reward = 50000 if 'important' in completion or 'relevant' in completion else -10000
    concise_reward = 20000 if len(completion.split()) < 50 else -5000
    total_reward = informative_reward + concise_reward
    return max(min(total_reward, 100000), -100000)
